static bool TryBuy(ref int stock)
{
    while (true)
    {
        int current = Volatile.Read(ref stock);
        if (current <= 0) return false;
        int previous = Interlocked.CompareExchange(ref stock, current - 1, current);
        if (previous == current) return true;
    }
}

